  lines.push(
    ...list(
      "Failed to parse",
      coverage.failed.map((f) => `\`${code(f.file)}\` (${md(f.parserId)}): ${md(f.reason)}`)
    )
  );
  lines.push("");
  if (options.isFork)
    lines.push("This pull request comes from a fork, so it was analyzed only. Nothing was sent anywhere.");
  else if (options.mode === "analyze") lines.push("Mode: analyze. Nothing was sent anywhere.");
  lines.push(`The Artifact is in \`${code(options.artifactFile)}\`.`);
