    apiUrl,
    token,
    body: {
      artifact,
      committedAt: date5.date,
      ...mode === "diff" && comment ? { comment } : {},
      ...mode === "diff" && context.pullRequest ? {
        pullRequest: {
          number: context.pullRequest.number,
          headRepositoryId: context.pullRequest.headRepositoryId,
          ...context.pullRequest.title ? { title: context.pullRequest.title } : {}
        }
      } : {}
    },
    ...io.fetchFn ? { fetchFn: io.fetchFn } : {},
    ...io.sleep ? { sleep: io.sleep } : {}
