  if (!result.ok) {
    const why = result.status === 0 ? "could not reach Sketio Arch" : `Sketio Arch answered ${result.status}`;
    for (const d of result.details ?? []) io.log(plainLine(`  ${d}`));
    return fail(`Sending the analysis failed: ${why} (${result.error}).`);
  }
  const r = result.response;
  io.log(
    `sent to Sketio Arch: ${r.outcome}${r.snapshotId ? ` (snapshot ${plainLine(r.snapshotId)})` : ""}${r.diff ? `; diff ${plainLine(r.diff.id)}` : ""}`
  );
  if (r.warnings?.length)
    io.log(
      issue(
        "warning",
        `The analysis was saved, but writing to the pull request failed (${r.warnings.join(", ")}). Check the Sketio GitHub App's permissions.`
      )
    );
